                    support = Decimal(0)
                    unstable = Decimal(0)
                    nonsignificant = Decimal(0)
                    direction = Decimal(0)
                    for panel_key in members:
                        weight = weight_values[panel_key]
                        contribution += (
                            weight
                            * panels[panel_key]["ranks"][scenario_key][2]
