def _decision_priority_parse(raw: object, label: str) -> dict:
    """Parse and validate a ``decision_priority_matrix`` JSON output.

    Returns ``{(by, key): {candidate key: rank}}``; any structural
    violation raises ``ValueError`` naming ``label``.
